"""Small text statistics helpers used by the blog editor."""


def word_count(text):
    """Return the number of words in text."""
    return len(text.split(" "))


def char_count(text, include_spaces=True):
    """Return the number of characters, optionally ignoring spaces."""
    if include_spaces:
        return len(text)
    return len(text.replace(" ", ""))


def reading_time_minutes(text, wpm=200):
    """Estimated reading time, rounded up to whole minutes (minimum 1)."""
    words = word_count(text)
    return max(1, -(-words // wpm))

