import re


def slugify(title):
    """Turn a post title into a URL slug."""
    return re.sub(r"[^a-z0-9]+", "-", title)
def unique_slug(title, existing):
    """Slug for title that isn't already in existing (adds -2, -3, ...)."""
    base = slugify(title)
    slug, n = base, 2
    while slug in existing:
        slug = f"{base}-{n}"
        n += 1
    return slug

