def line_total(qty, unit_price):
    """Total for one invoice line, rounded to cents."""
    return round(qty * unit_price, 2)


def invoice_total(lines):
    """Sum of line totals for (qty, unit_price) pairs."""
    return round(sum(line_total(q, p) for q, p in lines), 2)
def apply_tax(amount, rate):
    """amount plus tax at rate (0.08 = 8%), rounded to cents."""
    return round(amount * (1 + rate), 2)

