"""Retry wrapper around the inventory API client."""
import time


class HTTPError(Exception):
    def __init__(self, status):
        super().__init__(f"HTTP {status}")
        self.status = status


def fetch_with_retry(fetch, attempts=3, delay=0.5, sleep=time.sleep):
    """Call fetch() until it succeeds, retrying on HTTPError."""
    for attempt in range(attempts):
        try:
            return fetch()
        except HTTPError:
            if attempt == attempts - 1:
                raise
            sleep(delay)

