    assert fetch_with_retry(lambda: 42, sleep=no_sleep) == 42


def test_retries_server_error_then_succeeds():
    calls = []

    def fetch():
        calls.append(1)
        if len(calls) == 1:
            raise HTTPError(503)
        return "ok"

    assert fetch_with_retry(fetch, sleep=no_sleep) == "ok"
    assert len(calls) == 2


def test_gives_up_after_all_attempts():
    calls = []

    def fetch():
        calls.append(1)
        raise HTTPError(500)

    with pytest.raises(HTTPError):
        fetch_with_retry(fetch, sleep=no_sleep)
    assert len(calls) == 3

