"""Request handlers for the small internal web app."""


def handle_home(req):
    return {"status": 200, "body": "home"}


def handle_login(req):
    user = req.get("user")
    if not user:
        return {"status": 401, "body": "missing user"}
    return {"status": 200, "body": f"welcome {user}"}


def handle_legacy_login(req):
    return {"status": 301, "body": "/login"}


def handle_export(req):
    rows = req.get("rows", [])
    return {"status": 200, "body": "\n".join(",".join(map(str, r)) for r in rows)}


def handle_old_upload(req):
    if "file" not in req:
        return {"status": 400, "body": "no file"}
    return {"status": 201, "body": "stored"}


ROUTES = {
    "/": handle_home,
    "/login": handle_login,
    "/v1/upload": handle_old_upload,  # v1 mobile clients
}


def dispatch(path, req):
    handler = ROUTES.get(path)
    if handler is None:
        return {"status": 404, "body": "not found"}
    return handler(req)

