"""Revenue stats over users and orders."""


def revenue_by_plan(users, orders):
    """Total order value per plan; orders for unknown users are skipped."""
    plan_of = {u["id"]: u["plan"] for u in users}
    out = {}
    for order in orders:
        plan = plan_of.get(order["user_id"])
        if plan is None:
            continue
        out[plan] = round(out.get(plan, 0.0) + order["total"], 2)
    return out


def display_name(user):
    """Name to show in the UI; falls back to the id for blank names."""
    return user["name"] or f"user {user['id']}"

